// src/api/content_i18n/ContentI18n.ts
init_IdentityLocale();
init_CreateStaticI18n();
init_MessageCatalogTypes();
var DEFAULT_LOCALE4 = "en-US";
var contentI18n = createStaticI18n(
  {
    defaultLocale: DEFAULT_LOCALE4,
    defaultMessages: CONTENT_I18N_MESSAGES,
    localeMessages: CONTENT_I18N_LOCALE_MESSAGES,
    normalizeLocale: (locale) => identityLocale(locale),
    onWarning: (message) => {
      console.warn(message);
    },
    validateVariables: (_key, template, variables) => validateMessageTemplateVariables(template, variables)
  },
  (template, variables, mf) => {
    return String(mf.compile(template)(variables));
  }
);
function getContentMessage(key2, locale, ...args) {
  const variables = args[0];
  const result = contentI18n.getTemplate(key2, locale ?? null, variables ?? {});
  if (result.ok) {
    return result.value;
  }
  console.warn(`Missing translation for content message: ${key2} (locale: ${locale ?? DEFAULT_LOCALE4})`);
  return key2;
}

// src/api/auth/AuthLogin.ts
init_InstanceConfigRepository();
init_Logger();
init_RequestCacheMiddleware();
init_ServiceSingletons();
init_IpUtils();

// src/api/utils/RateLimitUtils.ts
init_RateLimitError();
function getRetryAfterSeconds(result) {
  return result.retryAfter ?? Math.max(0, Math.ceil((result.resetTime.getTime() - Date.now()) / 1e3));
}
function createRateLimitError(result) {
  return new RateLimitError({
    retryAfter: getRetryAfterSeconds(result),
    limit: result.limit,
    resetTime: result.resetTime
  });
}

