// src/api/invite/InviteModel.ts
async function mapInviteToGuildInviteResponse({
  invite,
  userCacheService,
  requestCache,
  getChannelResponse,
  getGuildResponse,
  getGuildCounts,
  gatewayService
}) {
  if (!invite.guildId) {
    throw new UnknownInviteError();
  }
  let channelId = invite.channelId;
  if (!channelId) {
    const resolvedChannelId = await gatewayService.getFirstViewableTextChannel(invite.guildId);
    if (!resolvedChannelId) {
      throw new UnknownInviteError();
    }
    channelId = resolvedChannelId;
  }
  const [channel, guild, inviter, counts] = await Promise.all([
    getChannelResponse(channelId),
    getGuildResponse(invite.guildId),
    invite.inviterId ? getCachedUserPartialResponse({
      userId: invite.inviterId,
      userCacheService,
      requestCache
    }) : null,
    getGuildCounts(invite.guildId)
  ]);
  const expiresAt = invite.maxAge > 0 ? new Date(invite.createdAt.getTime() + invite.maxAge * 1e3) : null;
  return {
    code: invite.code,
    type: InviteTypes.GUILD,
    guild,
    channel,
    inviter,
    member_count: counts.memberCount,
    presence_count: counts.presenceCount,
    expires_at: expiresAt?.toISOString() ?? null,
    temporary: invite.temporary
  };
}
async function mapInviteToGuildInviteMetadataResponse({
  invite,
  userCacheService,
  requestCache,
  getChannelResponse,
  getGuildResponse,
  getGuildCounts,
  gatewayService
}) {
  const baseResponse = await mapInviteToGuildInviteResponse({
    invite,
    userCacheService,
    requestCache,
    getChannelResponse,
    getGuildResponse,
    getGuildCounts,
    gatewayService
  });
  return {
    ...baseResponse,
    created_at: invite.createdAt.toISOString(),
    uses: invite.uses,
    max_uses: invite.maxUses,
    max_age: invite.maxAge
  };
}
async function mapInviteToGroupDmInviteResponse({
  invite,
  userCacheService,
  requestCache,
  getChannelResponse,
  getChannelSystem,
  getChannelMemberCount
}) {
  if (!invite.channelId) {
    throw new UnknownInviteError();
  }
  const [channel, inviter, memberCount, channelSystem] = await Promise.all([
    getChannelResponse(invite.channelId),
    invite.inviterId ? getCachedUserPartialResponse({
      userId: invite.inviterId,
      userCacheService,
      requestCache
    }) : null,
    getChannelMemberCount(invite.channelId),
    getChannelSystem(invite.channelId)
  ]);
  if (!channelSystem) {
    throw new UnknownInviteError();
  }
  const recipientIds = Array.from(channelSystem.recipientIds);
  const recipientPartials = await getCachedUserPartialResponses({
    userIds: recipientIds,
    userCacheService,
    requestCache
  });
  const recipients = recipientIds.map((recipientId) => {
    const recipientPartial = recipientPartials.get(recipientId);
    if (!recipientPartial) {
      throw new UnknownInviteError();
    }
    return { username: recipientPartial.username };
  });
  const channelWithRecipients = { ...channel, recipients };
  const expiresAt = invite.maxAge > 0 ? new Date(invite.createdAt.getTime() + invite.maxAge * 1e3) : null;
  return {
    code: invite.code,
    type: InviteTypes.GROUP_DM,
    channel: channelWithRecipients,
    inviter,
    member_count: memberCount,
    expires_at: expiresAt?.toISOString() ?? null,
    temporary: invite.temporary
  };
}
async function mapInviteToGroupDmInviteMetadataResponse({
  invite,
  userCacheService,
  requestCache,
  getChannelResponse,
  getChannelSystem,
  getChannelMemberCount
}) {
  const baseResponse = await mapInviteToGroupDmInviteResponse({
    invite,
    userCacheService,
    requestCache,
    getChannelResponse,
    getChannelSystem,
    getChannelMemberCount
  });
  return {
    ...baseResponse,
    created_at: invite.createdAt.toISOString(),
    uses: invite.uses,
    max_uses: invite.maxUses
  };
}

