function getPrimarySubscriptionItem(subscription) {
  const items = subscription.items?.data ?? [];
  if (items.length === 0) {
    return null;
  }
  const recurringItem = items.find((item) => Boolean(item.price?.recurring));
  return recurringItem ?? items[0];
}
function getSubscriptionItemPeriodEndUnix(item) {
  return item?.current_period_end ?? null;
}
function getSubscriptionItemPeriodEnd(item) {
  const periodEnd = getSubscriptionItemPeriodEndUnix(item);
  return periodEnd == null ? null : new Date(periodEnd * 1e3);
}
function getSubscriptionEntitlementPeriodEndUnix(subscription, item) {
  const periodEnd = getSubscriptionItemPeriodEndUnix(item);
  const trialEnd = subscription.trial_end ?? null;
  if (trialEnd != null && periodEnd != null) {
    return Math.max(trialEnd, periodEnd);
  }
  return trialEnd ?? periodEnd;
}
function getSubscriptionCurrentPeriodEnd(subscription) {
  const items = subscription.items?.data ?? [];
  if (items.length === 0) {
    return null;
  }
  let latestPeriodEnd = null;
  for (const item of items) {
    if (item.current_period_end == null) {
      continue;
    }
    if (latestPeriodEnd == null || item.current_period_end > latestPeriodEnd) {
      latestPeriodEnd = item.current_period_end;
    }
  }
  return latestPeriodEnd == null ? null : new Date(latestPeriodEnd * 1e3);
}
function getSubscriptionPremiumPeriodEnd(subscription) {
  if (subscription.cancel_at) {
    return new Date(subscription.cancel_at * 1e3);
  }
  const trialEnd = subscription.trial_end ? new Date(subscription.trial_end * 1e3) : null;
  const currentPeriodEnd = getSubscriptionCurrentPeriodEnd(subscription);
  if (trialEnd && currentPeriodEnd) {
    return trialEnd > currentPeriodEnd ? trialEnd : currentPeriodEnd;
  }
  return trialEnd ?? currentPeriodEnd;
}
function getSubscriptionStartDate(subscription) {
  return new Date((subscription.start_date ?? subscription.created) * 1e3);
}
function getInvoiceLatestLinePeriodEnd(invoice) {
  const lines = invoice.lines?.data ?? [];
  let latestPeriodEndUnix = null;
  for (const line of lines) {
    const periodEnd = line.period?.end ?? null;
    if (periodEnd && (latestPeriodEndUnix === null || periodEnd > latestPeriodEndUnix)) {
      latestPeriodEndUnix = periodEnd;
    }
  }
  return latestPeriodEndUnix ? new Date(latestPeriodEndUnix * 1e3) : null;
}
function getFirstInvoicePaymentIntent(invoice) {
  const invoiceWithPayments = invoice;
  const entries = invoiceWithPayments?.payments?.data ?? [];
  for (const entry of entries) {
    const paymentIntent = entry.payment?.payment_intent ?? null;
    if (paymentIntent) {
      return paymentIntent;
    }
  }
  return null;
}
function getFirstInvoicePaymentIntentId(invoice) {
  const paymentIntent = getFirstInvoicePaymentIntent(invoice);
  if (!paymentIntent) {
    return null;
  }
  if (typeof paymentIntent === "string") {
    return paymentIntent;
  }
  return paymentIntent.id ?? null;
}

