import { ms as ms44, seconds as seconds31 } from "itty-time";
var INACTIVITY_WARNING_TTL_DAYS = 30;
var INACTIVITY_WARNING_PREFIX = "inactivity_warning_sent";
var UserDeletionEligibilityService = class {
  constructor(kvClient) {
    this.kvClient = kvClient;
  }
  kvClient;
  async isEligibleForInactivityDeletion(user) {
    if (user.isBot) {
      return false;
    }
    if (user.isSystem) {
      return false;
    }
    if (this.isAppStoreReviewer(user)) {
      return false;
    }
    if (user.pendingDeletionAt !== null) {
      return false;
    }
    if (user.lastActiveAt === null) {
      return false;
    }
    const inactivityThresholdMs = this.getInactivityThresholdMs();
    const lastActiveAt = getValidTimestamp(user.lastActiveAt, `Last activity timestamp for user ${user.id}`);
    return Date.now() - lastActiveAt >= inactivityThresholdMs;
  }
  async isEligibleForWarningEmail(user) {
    const isEligibleForDeletion = await this.isEligibleForInactivityDeletion(user);
    if (!isEligibleForDeletion) {
      return false;
    }
    return !await this.hasWarningSent(user.id);
  }
  async markWarningSent(userId) {
    const key2 = this.getWarningKey(userId);
    const ttlSeconds = seconds31(`${INACTIVITY_WARNING_TTL_DAYS + 5} days`);
    const timestamp = Date.now().toString();
    await this.kvClient.setex(key2, ttlSeconds, timestamp);
  }
  async hasWarningSent(userId) {
    const key2 = this.getWarningKey(userId);
    const exists = await this.kvClient.exists(key2);
    return exists === 1;
  }
  async getWarningSentTimestamp(userId) {
    const key2 = this.getWarningKey(userId);
    return parseStoredTimestamp(await this.kvClient.get(key2), `Inactivity warning timestamp for user ${userId}`);
  }
  async hasWarningGracePeriodExpired(userId) {
    const timestamp = await this.getWarningSentTimestamp(userId);
    if (timestamp === null) {
      return false;
    }
    const timeSinceWarningMs = Date.now() - timestamp;
    const gracePeriodMs = INACTIVITY_WARNING_TTL_DAYS * ms44("1 day");
    return timeSinceWarningMs >= gracePeriodMs;
  }
  getInactivityThresholdMs() {
    const thresholdDays = Config.inactivityDeletionThresholdDays ?? 365 * 2;
    return thresholdDays * ms44("1 day");
  }
  getWarningKey(userId) {
    return `${INACTIVITY_WARNING_PREFIX}:${userId}`;
  }
  isAppStoreReviewer(user) {
    return (user.flags & UserFlags.APP_STORE_REVIEWER) !== 0n;
  }
};

